INSERT INTO location_translations(location_id,locale,name,summary,status,aliases,detail,literary_significance,historical_background,modern_status,historical_region_name)
SELECT l.id,v.locale::locale_code,v.name,v.summary,'published',v.aliases,v.detail,v.significance,v.background,v.modern_status,v.region FROM locations l JOIN (VALUES
('ararat-mountains','zh-CN','亚拉腊山地','洪水叙事结束时方舟停靠的山地区域。',ARRAY['亚拉腊']::text[],'文本说的是「亚拉腊的山」，即一片山地而非某座具体山峰；本样本以土耳其东部的亚拉腊山作为惯用参照点并标记为推定。','标记洪水叙事的终点与新的开端。','古代乌拉尔图地区的高地。','山体位于今土耳其东部，可远观。','古代亚美尼亚 / 乌拉尔图'),
('ararat-mountains','en','Mountains of Ararat','The highland region where the ark comes to rest at the end of the flood narrative.',ARRAY['Ararat']::text[],'The text names a range, not a peak; this sample uses Mount Ararat in eastern Türkiye as the conventional reference and marks it inferred.','It marks the end of the flood narrative and a fresh start.','Highlands of the ancient Urartu region.','The massif lies in eastern Türkiye and is visible from a distance.','Ancient Armenia / Urartu'),
('babylon','zh-CN','巴比伦','巴别叙事与被掳叙事共用的美索不达米亚城市。',ARRAY['巴别']::text[],'同一地点在起源叙事中作为语言分散的场景，在王国末期作为流放目的地。','把起源叙事的「分散」主题与历史叙事的「被掳」主题连成一条线。','新巴比伦帝国都城。','伊拉克希拉附近的考古遗址。','巴比伦尼亚'),
('babylon','en','Babylon','A Mesopotamian city shared by the Babel narrative and the exile narrative.',ARRAY['Babel']::text[],'The same site serves as the scene of linguistic dispersal in the origin narrative and as the destination of deportation at the end of the monarchy.','It links the dispersal theme of the origin narrative to the exile theme of the historical narrative.','Capital of the Neo-Babylonian empire.','An archaeological site near Hillah, Iraq.','Babylonia'),
('hebron','zh-CN','希伯仑','族长家族墓地与大卫最初作王的城市。',ARRAY['幔利']::text[],'地图使用现代希伯仑城市中心。','把族长叙事与王国叙事绑定在同一座城市。','犹大山地的古老城市。','现代城市仍存，古迹受到管理。','犹大山地'),
('hebron','en','Hebron','The patriarchal burial city and David’s first royal seat.',ARRAY['Mamre']::text[],'The map uses the modern city centre.','It binds the patriarchal and monarchic narratives to a single city.','An ancient city of the Judean hill country.','The modern city persists and its historic sites are administered.','Judean hill country'),
('beersheba','zh-CN','别是巴','族长叙事中南部边界的水井与定居点。',ARRAY[]::text[],'常被用作「南界」的地理表达。','标记族长活动范围的南端。','内盖夫北缘的古代聚落。','现代别是巴为以色列南部主要城市。','内盖夫'),
('beersheba','en','Beersheba','A well and settlement marking the southern edge in patriarchal narratives.',ARRAY[]::text[],'Frequently used as the conventional expression for the southern limit.','It marks the southern end of the patriarchal range.','An ancient settlement on the northern Negev.','Modern Beersheba is a major city in southern Israel.','Negev'),
('sodom-region','zh-CN','所多玛地区','族长叙事中被毁城邑所在的死海南端区域。',ARRAY['蛾摩拉']::text[],'具体城址未有共识，坐标仅表示死海南端区域，标记为推定。','承载审判与营救的叙事主题。','死海南端的古代低地。','区域仍存，城址不确定。','约旦河谷南段'),
('sodom-region','en','Sodom region','The southern Dead Sea area of the destroyed cities in the patriarchal narrative.',ARRAY['Gomorrah']::text[],'No consensus site exists; the coordinate stands for the southern Dead Sea area and is marked inferred.','It carries the narrative themes of judgement and rescue.','An ancient lowland at the southern Dead Sea.','The region persists; the city sites remain unidentified.','Southern Jordan valley'),
('bethel','zh-CN','伯特利','雅各梦境叙事与后期北国祭祀叙事的地点。',ARRAY['路斯']::text[],'惯用参照点在今拜廷附近，学界仍有讨论。','连接族长个人经历与后来的群体祭祀争议。','中部山地的古代圣所。','遗址位于西岸地区。','以法莲山地'),
('bethel','en','Bethel','The setting of Jacob’s dream and of later northern-kingdom cult narratives.',ARRAY['Luz']::text[],'The conventional reference lies near modern Beitin; the identification is still discussed.','It connects a patriarch’s private experience with later collective cultic disputes.','An ancient sanctuary in the central hill country.','The site lies in the West Bank.','Hill country of Ephraim'),
('peniel-jabbok','zh-CN','毗努伊勒（雅博渡口）','雅各夜间摔跤叙事的渡口地点。',ARRAY['雅博河']::text[],'渡口位置以雅博河（今扎尔卡河）河谷推定。','雅各改名以色列的转折地点。','外约旦的河谷通道。','扎尔卡河谷仍可辨认。','基列'),
('peniel-jabbok','en','Peniel (Jabbok ford)','The ford where the night-wrestling narrative of Jacob takes place.',ARRAY['Jabbok']::text[],'The ford is inferred from the valley of the Jabbok, today the Zarqa.','The turning point where Jacob is renamed Israel.','A valley crossing in Transjordan.','The Zarqa valley remains identifiable.','Gilead'),
('goshen','zh-CN','歌珊地','雅各家族在埃及定居的三角洲东部区域。',ARRAY[]::text[],'区域范围未有定论，坐标取三角洲东部近似中心。','把族长叙事与出埃及叙事衔接起来。','古埃及三角洲东部牧地。','今属埃及东部三角洲。','下埃及'),
('goshen','en','Goshen','The eastern delta region where Jacob’s household settles in Egypt.',ARRAY[]::text[],'The extent is unsettled; the coordinate is an approximate eastern-delta centre.','It joins the patriarchal narrative to the Exodus narrative.','Pastoral land in the eastern Egyptian delta.','Part of the eastern Nile delta today.','Lower Egypt'),
('reed-sea-crossing','zh-CN','海口渡越处（推定）','出埃及叙事中渡海事件的推定位置。',ARRAY['芦苇海']::text[],'候选位置有多处，本样本取苏伊士地峡一带作为示意，明确标记为推定。','出埃及叙事中最具标志性的转折。','古代苏伊士地峡的湖沼地带。','地貌因运河工程大幅改变。','西奈边缘'),
('reed-sea-crossing','en','Sea crossing (inferred)','The inferred location of the sea crossing in the Exodus narrative.',ARRAY['Reed Sea']::text[],'Several candidates exist; this sample uses the Suez isthmus area as an indicative point and marks it inferred.','The most emblematic turning point of the Exodus narrative.','The ancient lake and marsh belt of the Suez isthmus.','The landscape has been reshaped by canal works.','Sinai margin'),
('kadesh-barnea','zh-CN','加低斯巴尼亚','旷野叙事中长期停留与探子事件的绿洲。',ARRAY[]::text[],'常与今艾因库代拉特一带对应，仍属推定。','旷野漂流叙事的核心据点。','内盖夫南部的绿洲。','绿洲仍存，位于埃及—以色列边境地带。','旷野'),
('kadesh-barnea','en','Kadesh-barnea','The oasis of the long wilderness stay and the scouting episode.',ARRAY[]::text[],'Usually identified with the area of Ain el-Qudeirat; the identification remains inferred.','The central base of the wilderness-wandering narrative.','An oasis in the southern Negev.','The oasis survives near the Egypt–Israel border zone.','Wilderness'),
('mount-nebo','zh-CN','尼波山','摩西远望迦南、生命终结的叙事地点。',ARRAY['毗斯迦']::text[],'今约旦尼波山为传统地点，可俯瞰约旦河谷。','律法者叙事的收束点。','摩押高地的边缘山脊。','现为约旦的纪念地与观景点。','摩押'),
('mount-nebo','en','Mount Nebo','Where Moses looks out over Canaan and the narrative of his life ends.',ARRAY['Pisgah']::text[],'The traditional site in Jordan overlooks the Jordan valley.','The closing point of the lawgiver narrative.','A ridge on the edge of the Moabite plateau.','A memorial site and viewpoint in Jordan today.','Moab'),
('jericho','zh-CN','耶利哥','进入迦南叙事的第一座城，也是新约叙事的经过地。',ARRAY[]::text[],'古城遗址（苏丹土丘）与现代城镇相邻。','跨越旧约征战叙事与新约行程叙事。','世界最古老的有人居住地之一。','现代耶利哥与考古遗址并存。','约旦河谷'),
('jericho','en','Jericho','The first city of the entry narrative and a waypoint in New Testament journeys.',ARRAY[]::text[],'The ancient mound of Tell es-Sultan sits beside the modern town.','It spans the conquest narratives and later travel narratives.','One of the longest continuously inhabited places known.','The modern town and the archaeological mound coexist.','Jordan valley'),
('shiloh','zh-CN','示罗','士师时期的中央圣所与撒母耳幼年叙事地点。',ARRAY[]::text[],'今谢洛遗址为惯用对应地点。','王国出现之前的宗教中心。','中部山地的古代聚落。','考古遗址位于西岸地区。','以法莲山地'),
('shiloh','en','Shiloh','The central sanctuary of the judges period and the setting of Samuel’s childhood.',ARRAY[]::text[],'The site of Khirbet Seilun is the conventional identification.','A religious centre before the monarchy appears.','An ancient settlement in the central hill country.','The archaeological site lies in the West Bank.','Hill country of Ephraim'),
('gaza','zh-CN','迦萨','非利士城邦之一，参孙叙事的收束地点。',ARRAY[]::text[],'地图使用现代城市中心。','士师叙事中冲突与结局的场所。','古代非利士五城之一。','现代迦萨城仍存。','非利士地'),
('gaza','en','Gaza','One of the Philistine cities and the closing setting of the Samson narrative.',ARRAY[]::text[],'The map uses the modern city centre.','The site of conflict and conclusion in the judges narrative.','One of the five ancient Philistine cities.','The modern city persists.','Philistia'),
('valley-of-elah','zh-CN','以拉谷','大卫与歌利亚对峙叙事的谷地。',ARRAY[]::text[],'谷地位置明确，具体对阵点不可考。','少年与巨人主题的经典场景。','犹大低地通往山地的通道。','谷地仍可实地辨认。','示非拉'),
('valley-of-elah','en','Valley of Elah','The valley of the David and Goliath confrontation.',ARRAY[]::text[],'The valley is identifiable; the precise standoff point is not.','The classic setting of the youth-versus-giant theme.','A corridor from the Judean lowland into the hills.','The valley remains identifiable on the ground.','Shephelah'),
('ramah','zh-CN','拉玛','撒母耳的家乡与膏立叙事的出发地。',ARRAY[]::text[],'候选地点有数处，标记为推定。','连接士师时代与王国时代的枢纽人物所在地。','便雅悯地区的古代城镇。','对应地点存在争议。','便雅悯'),
('ramah','en','Ramah','Samuel’s home town and the starting point of the anointing narratives.',ARRAY[]::text[],'Several candidate sites exist; the identification is marked inferred.','Home of the figure who links the judges period to the monarchy.','An ancient town in the Benjamin region.','The identification is disputed.','Benjamin'),
('mount-gilboa','zh-CN','基利波山','扫罗王朝终结的战场。',ARRAY[]::text[],'山脊范围明确，战场具体位置为近似。','旧王朝结束、新王朝开始的分界。','耶斯列谷东南的山脊。','山地仍存，为以色列北部景观。','耶斯列谷'),
('mount-gilboa','en','Mount Gilboa','The battlefield where the house of Saul comes to an end.',ARRAY[]::text[],'The ridge is well identified; the battle point itself is approximate.','The boundary between the old dynasty and the new.','A ridge southeast of the Jezreel valley.','The range remains part of the northern Israeli landscape.','Jezreel valley'),
('megiddo','zh-CN','米吉多','控制通道的要塞城市，多次战役叙事的地点。',ARRAY[]::text[],'考古遗址位置确定。','把地理要道与政治权力联系起来。','青铜与铁器时代的重要要塞。','联合国教科文组织世界遗产。','耶斯列谷'),
('megiddo','en','Megiddo','A fortress city commanding a pass and the setting of several battle narratives.',ARRAY[]::text[],'The archaeological site is securely located.','It ties a geographic corridor to political power.','A major Bronze and Iron Age fortress.','A UNESCO World Heritage site.','Jezreel valley'),
('samaria-sebaste','zh-CN','撒玛利亚','北国以色列的都城。',ARRAY['西巴斯特']::text[],'遗址位于今塞巴斯提亚附近。','北国政治与宗教叙事的中心。','暗利王朝建立的都城。','考古遗址位于西岸地区。','以色列（北国）'),
('samaria-sebaste','en','Samaria','The capital of the northern kingdom of Israel.',ARRAY['Sebaste']::text[],'The site lies near modern Sebastia.','The centre of northern political and religious narratives.','The capital founded by the Omride dynasty.','The archaeological site lies in the West Bank.','Israel (northern kingdom)'),
('mount-carmel','zh-CN','迦密山','以利亚叙事中对峙事件的山脊。',ARRAY[]::text[],'山脊范围明确，具体地点为传统对应。','先知叙事中最具戏剧性的公开场面。','地中海沿岸的石灰岩山脊。','以色列海法一带的自然公园。','以色列（北国）'),
('mount-carmel','en','Mount Carmel','The ridge of the confrontation episode in the Elijah narrative.',ARRAY[]::text[],'The ridge is well defined; the specific spot is traditional.','The most dramatic public scene in the prophetic narratives.','A limestone ridge on the Mediterranean coast.','A nature park in the Haifa area of Israel.','Israel (northern kingdom)'),
('lachish','zh-CN','拉吉','亚述围城叙事中犹大的第二大城。',ARRAY[]::text[],'亚述浮雕留下围城场面，是少见的图像旁证。','把文本叙事与外部图像证据对照。','犹大低地的要塞城市。','考古遗址位于以色列南部。','犹大'),
('lachish','en','Lachish','Judah’s second city in the Assyrian siege narratives.',ARRAY[]::text[],'Assyrian reliefs depict the siege, a rare external pictorial witness.','It allows the text to be set beside external pictorial evidence.','A fortress city of the Judean lowland.','The archaeological site lies in southern Israel.','Judah'),
('susa','zh-CN','书珊','以斯帖与但以理叙事中的波斯宫廷所在地。',ARRAY['苏萨']::text[],'古代埃兰与波斯的都城之一。','把被掳后的群体叙事放进帝国宫廷背景。','阿契美尼德王朝的行政中心之一。','伊拉克境外的伊朗舒什遗址。','埃兰 / 波斯'),
('susa','en','Susa','The Persian court setting of the Esther and Daniel narratives.',ARRAY['Shushan']::text[],'One of the capitals of ancient Elam and Persia.','It places post-exilic community narratives in an imperial court setting.','An administrative centre of the Achaemenid empire.','The site of Shush in Iran.','Elam / Persia'),
('joppa','zh-CN','约帕','约拿登船出发的港口，也是彼得异象叙事地点。',ARRAY['雅法']::text[],'今特拉维夫—雅法的老城港区。','同一港口出现在旧约逃避叙事与新约转向叙事中。','古代地中海东岸的重要港口。','雅法老城仍存并对外开放。','沿海平原'),
('joppa','en','Joppa','The port where Jonah embarks and the setting of Peter’s vision narrative.',ARRAY['Jaffa']::text[],'Today the old port quarter of Tel Aviv-Yafo.','The same harbour appears in an avoidance narrative and in a turning-point narrative.','A major port of the ancient eastern Mediterranean.','The old town of Jaffa remains and is open to visitors.','Coastal plain'),
('tarshish-reference','zh-CN','他施（推定参照）','约拿叙事中「相反方向」的远方目的地。',ARRAY[]::text[],'他施位置无定论，常见推测指向西地中海；本样本取西班牙南部作为方向性参照并明确标记为推定。','以地理距离表达「逃离使命」这一主题。','古代西地中海的贸易远端。','未确认的地点。','西地中海（推定）'),
('tarshish-reference','en','Tarshish (inferred reference)','The far destination in the opposite direction in the Jonah narrative.',ARRAY[]::text[],'Tarshish is unlocated; a common proposal points to the western Mediterranean. This sample uses southern Spain as a directional reference and marks it inferred.','It expresses the theme of fleeing a commission through geographic distance.','The far end of western Mediterranean trade in antiquity.','No confirmed site.','Western Mediterranean (inferred)'),
('capernaum','zh-CN','迦百农','福音书中加利利传道的常驻据点。',ARRAY[]::text[],'湖北岸考古遗址位置确定。','加利利叙事中出现频率最高的定点。','罗马时期的渔业与税关城镇。','考古遗址开放参观。','加利利'),
('capernaum','en','Capernaum','The base of the Galilean ministry in the Gospels.',ARRAY[]::text[],'The archaeological site on the northern lakeshore is securely located.','The most frequently recurring fixed point of the Galilean narrative.','A Roman-period fishing and customs town.','The archaeological site is open to visitors.','Galilee'),
('cana','zh-CN','迦拿','约翰福音首个神迹叙事的村镇。',ARRAY[]::text[],'有两处候选地点，标记为推定。','标志福音书叙事的开端场景。','加利利的小型聚落。','候选地点均在以色列北部。','加利利'),
('cana','en','Cana','The village of the first sign narrative in John.',ARRAY[]::text[],'Two candidate sites exist; the identification is marked inferred.','It marks an opening scene in that Gospel narrative.','A small Galilean settlement.','Both candidates lie in northern Israel.','Galilee'),
('bethsaida','zh-CN','伯赛大','数位门徒的家乡，湖东北岸聚落。',ARRAY[]::text[],'具体地点仍有争议，标记为推定。','把门徒群体与具体地理来源联系起来。','加利利湖东北岸的渔村。','两处候选遗址均在发掘中。','加利利'),
('bethsaida','en','Bethsaida','The home town of several disciples on the northeastern lakeshore.',ARRAY[]::text[],'The precise site remains disputed and is marked inferred.','It ties the disciple group to a concrete geographic origin.','A fishing village on the northeastern Sea of Galilee.','Two candidate sites are under excavation.','Galilee'),
('jordan-river-bethany','zh-CN','约旦河（伯大尼渡口）','洗礼叙事的传统地点。',ARRAY['约旦河东伯大尼']::text[],'今约旦一侧的传统受洗地。','福音书叙事公开阶段的起点。','约旦河下游渡口。','约旦一侧为世界遗产朝圣地。','约旦河谷'),
('jordan-river-bethany','en','Jordan River (Bethany crossing)','The traditional location of the baptism narrative.',ARRAY['Bethany beyond the Jordan']::text[],'The traditional site lies on the Jordanian bank.','The starting point of the public phase of the Gospel narrative.','A ford on the lower Jordan.','A World Heritage pilgrimage site on the Jordanian side.','Jordan valley'),
('mount-of-olives','zh-CN','橄榄山','耶路撒冷东侧山脊，最后一周多个场景的所在。',ARRAY[]::text[],'山脊位置明确，具体场景点为传统对应。','俯瞰圣殿区，是叙事的观察与转折位置。','耶路撒冷东侧的石灰岩山脊。','现代耶路撒冷东部，遗址与墓地密集。','犹太地'),
('mount-of-olives','en','Mount of Olives','The ridge east of Jerusalem and the setting of several final-week scenes.',ARRAY[]::text[],'The ridge is well defined; individual scene points are traditional.','Overlooking the temple area, it is the narrative’s vantage and turning point.','A limestone ridge east of Jerusalem.','In eastern Jerusalem today, dense with sites and cemeteries.','Judea'),
('golgotha-traditional','zh-CN','各各他（传统地点）','受难叙事的传统地点。',ARRAY['髑髅地']::text[],'传统地点位于圣墓教堂内，另有其他候选；标记为推定。','福音书叙事的高潮位置。','第一世纪耶路撒冷城墙外的采石与墓葬区。','位于耶路撒冷旧城内。','犹太地'),
('golgotha-traditional','en','Golgotha (traditional site)','The traditional site of the crucifixion narrative.',ARRAY['Calvary']::text[],'The traditional site lies within the Church of the Holy Sepulchre; other candidates exist, so it is marked inferred.','The climactic position of the Gospel narrative.','A first-century quarry and burial area outside the city wall.','Inside the Old City of Jerusalem.','Judea'),
('bethany-near-jerusalem','zh-CN','伯大尼','耶路撒冷东南的村镇，最后一周的住宿地。',ARRAY['伊萨维亚东侧']::text[],'今阿扎里耶一带。','提供最后一周叙事的私人空间对照。','橄榄山东坡的小型村落。','现代村镇仍存。','犹太地'),
('bethany-near-jerusalem','en','Bethany','A village southeast of Jerusalem used as lodging during the final week.',ARRAY[]::text[],'Today the area of al-Eizariya.','It supplies the private counterpoint to the public final-week narrative.','A small village on the eastern slope of the Mount of Olives.','The modern village persists.','Judea'),
('sychar-jacobs-well','zh-CN','叙加（雅各井）','约翰福音中撒玛利亚对话叙事的地点。',ARRAY['雅各井']::text[],'井址位于今纳布卢斯附近，长期有人使用。','把族长叙事与新约叙事叠加在同一口井上。','撒玛利亚地区的古老水井。','井仍存于教堂内。','撒玛利亚'),
('sychar-jacobs-well','en','Sychar (Jacob’s well)','The setting of the Samaritan conversation narrative in John.',ARRAY['Jacob’s well']::text[],'The well lies near modern Nablus and has been in continuous use.','It layers a patriarchal narrative and a Gospel narrative on one well.','An ancient well in the Samaria region.','The well survives inside a church.','Samaria'),
('mount-tabor','zh-CN','他泊山','士师叙事的集结点，也是变貌叙事的传统地点。',ARRAY[]::text[],'孤立山体位置明确。','同一座山承载旧约战事与新约异象两类叙事。','耶斯列谷东侧的孤峰。','以色列北部的景点。','加利利'),
('mount-tabor','en','Mount Tabor','A mustering point in the judges narrative and the traditional transfiguration site.',ARRAY[]::text[],'The isolated massif is securely located.','One mountain carries both a battle narrative and a vision narrative.','An isolated peak east of the Jezreel valley.','A visitor site in northern Israel.','Galilee'),
('emmaus-reference','zh-CN','以马忤斯（推定参照）','复活叙事中路上对话的目的地。',ARRAY[]::text[],'至少三处候选地点，本样本取其一并标记为推定。','以行走过程承载认出与回转的叙事。','耶路撒冷西侧的村落。','候选地点均在以色列中部。','犹太地'),
('emmaus-reference','en','Emmaus (inferred reference)','The destination of the road conversation in the resurrection narrative.',ARRAY[]::text[],'At least three candidates exist; this sample takes one and marks it inferred.','It carries recognition and reversal through the act of walking.','A village west of Jerusalem.','All candidates lie in central Israel.','Judea'),
('caesarea-maritima','zh-CN','该撒利亚','罗马行省港口，保罗受审与启程的地点。',ARRAY['海边该撒利亚']::text[],'考古遗址位置确定，含港口与剧场。','把犹太地叙事接入罗马行政体系。','希律建造的深水港城市。','以色列国家公园。','罗马犹太行省'),
('caesarea-maritima','en','Caesarea Maritima','The Roman provincial port where Paul is tried and from which he sails.',ARRAY['Caesarea by the sea']::text[],'The site is securely located and includes harbour and theatre remains.','It connects the Judean narrative to Roman administration.','A deep-water harbour city built by Herod.','An Israeli national park.','Roman province of Judea'),
('antioch-orontes','zh-CN','安提阿','早期跨族群群体的中心与宣教行程起点。',ARRAY['奥龙特斯河畔安提阿']::text[],'今土耳其安塔基亚。','早期群体从耶路撒冷向外扩展的枢纽。','塞琉古与罗马时期的大城市。','现代安塔基亚，2023 年地震后重建中。','罗马叙利亚'),
('antioch-orontes','en','Antioch on the Orontes','The centre of the early mixed community and the launch point of the missions.',ARRAY[]::text[],'Modern Antakya, Türkiye.','The hub from which the early community expands beyond Jerusalem.','A major Seleucid and Roman city.','Modern Antakya, rebuilding after the 2023 earthquakes.','Roman Syria'),
('tarsus','zh-CN','大数','保罗的出生城市。',ARRAY[]::text[],'今土耳其塔尔苏斯。','提供人物的公民身份与教育背景。','西里西亚的重要城市与学术中心。','现代城市仍存。','罗马西里西亚'),
('tarsus','en','Tarsus','Paul’s home city.',ARRAY[]::text[],'Modern Tarsus, Türkiye.','It supplies the figure’s civic status and educational background.','A leading city and centre of learning in Cilicia.','The modern city persists.','Roman Cilicia'),
('cyprus-salamis','zh-CN','塞浦路斯（撒拉米）','第一次宣教旅程的首站。',ARRAY[]::text[],'撒拉米遗址位于岛东岸。','宣教叙事离开大陆的第一步。','罗马时期塞浦路斯的主要城市。','考古遗址位于北塞浦路斯。','罗马塞浦路斯'),
('cyprus-salamis','en','Cyprus (Salamis)','The first stop of the first missionary journey.',ARRAY[]::text[],'The Salamis site lies on the island’s east coast.','The first step of the mission narrative away from the mainland.','A principal city of Roman Cyprus.','The archaeological site lies in northern Cyprus.','Roman Cyprus'),
('philippi','zh-CN','腓立比','马其顿的罗马殖民城市，欧洲行程的首站。',ARRAY[]::text[],'考古遗址位置确定。','叙事进入欧洲大陆的门槛。','罗马退伍军人殖民地。','希腊的世界遗产遗址。','罗马马其顿'),
('philippi','en','Philippi','A Roman colony in Macedonia and the first stop of the European itinerary.',ARRAY[]::text[],'The archaeological site is securely located.','The threshold at which the narrative enters mainland Europe.','A Roman veteran colony.','A World Heritage site in Greece.','Roman Macedonia'),
('thessalonica','zh-CN','帖撒罗尼迦','马其顿省会与书信收信城市。',ARRAY[]::text[],'现代塞萨洛尼基城市中心。','连接行程叙事与书信文本。','罗马马其顿行省首府。','希腊第二大城市。','罗马马其顿'),
('thessalonica','en','Thessalonica','The Macedonian provincial capital and a letter-recipient city.',ARRAY[]::text[],'The modern Thessaloniki city centre.','It links the itinerary narrative to the letter texts.','Capital of the Roman province of Macedonia.','Greece’s second city.','Roman Macedonia'),
('athens','zh-CN','雅典','公开辩论叙事的地点。',ARRAY[]::text[],'地图使用现代城市中心，叙事场景在亚略巴古一带。','把宣教叙事放进希腊哲学语境。','罗马时期的学术与宗教中心。','希腊首都。','罗马亚该亚'),
('athens','en','Athens','The setting of the public debate narrative.',ARRAY[]::text[],'The map uses the modern city centre; the scene is set near the Areopagus.','It places the mission narrative in a Greek philosophical context.','A centre of learning and religion in the Roman period.','The capital of Greece.','Roman Achaia'),
('corinth','zh-CN','哥林多','保罗长期停留的港口城市。',ARRAY[]::text[],'古哥林多遗址在现代城镇西南。','行程叙事中停留时间最长的据点之一。','连接两个海湾的贸易城市。','考古遗址开放参观。','罗马亚该亚'),
('corinth','en','Corinth','The port city where Paul stays for an extended period.',ARRAY[]::text[],'Ancient Corinth lies southwest of the modern town.','One of the longest stays in the itinerary narrative.','A trading city linking two gulfs.','The archaeological site is open to visitors.','Roman Achaia'),
('ephesus','zh-CN','以弗所','亚细亚省的大城，长期停留与冲突叙事地点。',ARRAY[]::text[],'考古遗址保存完好。','行程叙事中规模最大的城市场景。','罗马亚细亚行省的主要城市。','土耳其的世界遗产遗址。','罗马亚细亚'),
('ephesus','en','Ephesus','A major city of Asia and the setting of a long stay and a conflict narrative.',ARRAY[]::text[],'The archaeological site is well preserved.','The largest urban scene in the itinerary narrative.','A leading city of the Roman province of Asia.','A World Heritage site in Türkiye.','Roman Asia'),
('malta','zh-CN','马耳他','前往罗马途中船难与越冬的岛屿。',ARRAY['米利大']::text[],'岛屿位置确定，具体登陆点为传统对应。','航程叙事中断裂与延续的节点。','地中海中部的航路要点。','独立国家马耳他。','罗马地中海'),
('malta','en','Malta','The island of the shipwreck and overwintering on the way to Rome.',ARRAY['Melita']::text[],'The island is certain; the landing point is traditional.','The break-and-continue node of the voyage narrative.','A key waypoint in central Mediterranean shipping.','The independent state of Malta.','Roman Mediterranean'),
('patmos','zh-CN','拔摩','启示文本自述的写作地点。',ARRAY[]::text[],'爱琴海东部小岛。','把启示文本锚定在具体地理位置。','罗马时期的爱琴海岛屿。','希腊的世界遗产岛屿。','罗马亚细亚'),
('patmos','en','Patmos','The stated place of writing in the Revelation text.',ARRAY[]::text[],'A small island in the eastern Aegean.','It anchors an apocalyptic text to a concrete location.','An Aegean island in the Roman period.','A World Heritage island in Greece.','Roman Asia')
) AS v(slug,locale,name,summary,aliases,detail,significance,background,modern_status,region)
ON l.slug=v.slug AND l.work_id='10000000-0000-4000-8000-000000000005';

COMMIT;
